 private void showPhone(){PhoneCompanion.refresh();if(PhoneCompanion.connected()){Toast.makeText(this,"已连接",0).show();return;}List<NetworkState.Address> list=NetworkState.list();if(list.isEmpty()){Toast.makeText(this,"未发现局域网地址，请连接 Wi-Fi 或开启热点",1).show();return;}
  android.app.Dialog dialog=new android.app.Dialog(this);dialog.requestWindowFeature(android.view.Window.FEATURE_NO_TITLE);LinearLayout body=column();body.setPadding(dp(28),dp(22),dp(28),dp(22));body.setBackground(surface(Design.CARD,24));body.setClipToOutline(true);TextView title=Design.text(this,"手机助手",26);title.setGravity(android.view.Gravity.CENTER);body.addView(title);TextView help=Design.text(this,"手机连接同一网络，扫码后输入四位连接码",18);help.setGravity(android.view.Gravity.CENTER);body.addView(help);Spinner choices=new Spinner(this);List<String> labels=new ArrayList<>();for(NetworkState.Address n:list)labels.add(n.label());choices.setAdapter(new UiAdapter(this,labels));body.addView(choices);QrView qr=new QrView(this,PhoneCompanion.url(list.get(0).ip));LinearLayout.LayoutParams qp=new LinearLayout.LayoutParams(dp(230),dp(230));qp.gravity=android.view.Gravity.CENTER_HORIZONTAL;qp.topMargin=dp(10);qp.bottomMargin=dp(10);body.addView(qr,qp);TextView info=Design.text(this,"",21);info.setGravity(android.view.Gravity.CENTER);info.setTextIsSelectable(true);body.addView(info);TextView tip=Design.text(this,"也可在手机浏览器输入网址。连接成功后本弹窗会自动关闭。",16);tip.setGravity(android.view.Gravity.CENTER);body.addView(tip);Button close=Design.button(this,"关闭",dialog::dismiss);close.setBackground(Design.feedback(this,Design.ACCENT,12));close.setTextColor(Design.BG);LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(dp(230),dp(56));cp.gravity=android.view.Gravity.CENTER_HORIZONTAL;cp.topMargin=dp(16);body.addView(close,cp);dialog.setContentView(body);dialog.getWindow().setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Color.TRANSPARENT));dialog.getWindow().addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);WindowManager.LayoutParams attr=dialog.getWindow().getAttributes();attr.dimAmount=.58f;dialog.getWindow().setAttributes(attr);dialog.show();dialog.getWindow().setLayout(Math.min(dp(780),(int)(getResources().getDisplayMetrics().widthPixels*.88)),-2);
  Runnable update=()->{if(list.isEmpty())return;int selected=Math.max(0,Math.min(list.size()-1,choices.getSelectedItemPosition()));String url=PhoneCompanion.url(list.get(selected).ip);qr.setUrl(url);info.setText(url+"\n连接码："+PhoneCompanion.pin());};choices.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,android.view.View v,int n,long id){update.run();}});update.run();dialog.setOnDismissListener(d->phoneRefresh=null);phoneRefresh=()->{if(PhoneCompanion.connected()){dialog.dismiss();Toast.makeText(this,"已连接",0).show();return;}List<NetworkState.Address> fresh=NetworkState.list();StringBuilder before=new StringBuilder(),after=new StringBuilder();for(NetworkState.Address a:list)before.append(a.label());for(NetworkState.Address a:fresh)after.append(a.label());if(!before.toString().equals(after.toString())){list.clear();list.addAll(fresh);List<String> values=new ArrayList<>();for(NetworkState.Address a:list)values.add(a.label());if(values.isEmpty())values.add("暂无局域网地址");choices.setAdapter(new UiAdapter(this,values));}if(list.isEmpty()){qr.setUrl("");info.setText("网络已断开，请连接 Wi-Fi 或开启热点");}else update.run();};}
 private void prepareBridge(){try{File secretFile=new File(getFilesDir(),"bridge-token");if(!secretFile.exists()){byte[] random=new byte[16];new SecureRandom().nextBytes(random);StringBuilder b=new StringBuilder();for(byte n:random)b.append(String.format(Locale.US,"%02x",n&255));try(FileOutputStream out=new FileOutputStream(secretFile)){out.write(b.toString().getBytes("US-ASCII"));}}
  byte[] bytes=new byte[32];try(FileInputStream in=new FileInputStream(secretFile)){int offset=0,n;while(offset<32&&(n=in.read(bytes,offset,32-offset))>0)offset+=n;if(offset!=32)throw new IOException("授权信息异常，请重新打开星匣后重试");}bridgeSecret=new String(bytes,"US-ASCII");
  RootAccess.init(this);
 }catch(Exception e){String message="无法读取授权信息："+UserMessages.explain(e);output.setText(message);setRootMessage(message);}}
 private void refresh(){String old="";if(!ips.isEmpty()&&addresses.getSelectedItemPosition()<ips.size())old=ips.get(addresses.getSelectedItemPosition());networks.clear();networks.addAll(NetworkState.list());ips.clear();List<String> labels=new ArrayList<>();int selected=0;String peer=appliedIp;NetworkState.Address best=NetworkState.maintained(networks,peer,getSharedPreferences("connection",0).getString("adbInterface",""));for(int i=0;i<networks.size();i++){NetworkState.Address a=networks.get(i);ips.add(a.ip);labels.add(a.label());if(a.ip.equals(old)||a==best)selected=i;}if(labels.isEmpty()){labels.add("暂无局域网地址，请连接 Wi-Fi 或开启热点");networkStatus.setTextColor(Design.YELLOW);networkStatus.setText("暂无局域网地址，内网穿透仍可使用");}ArrayAdapter<String> adapter=new UiAdapter(this,labels,networks.isEmpty());adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);addresses.setAdapter(adapter);addresses.setSelection(selected);}
 private void refreshNetworkIfChanged(){List<NetworkState.Address> now=NetworkState.list();StringBuilder fresh=new StringBuilder(),old=new StringBuilder();for(NetworkState.Address a:now)fresh.append(a.label());for(NetworkState.Address a:networks)old.append(a.label());if(!fresh.toString().equals(old.toString())){refresh();if(rootAvailable||server!=null)readAdb();}}
 private String adbInterface(){if(networks.isEmpty())throw new IllegalArgumentException("请刷新网络地址");return networks.get(addresses.getSelectedItemPosition()).iface;}
 private void probe(){if(probing||server!=null||endingAuthorization){Toast.makeText(this,"请先停止回传或等待检测结束",0).show();return;}probing=true;probeButton.setEnabled(false);rootToggle.setChecked(false);rootToggle.setAllowed(false);setRootMessage("正在检测 Root 授权，请留意授权提示（最长 45 秒）…");new Thread(()->{CommandRunner.Result r=RootAccess.check(this,true);if(!dead)runOnUiThread(()->{if(endingAuthorization)return;probing=false;probeButton.setEnabled(true);bridgeMode=RootAccess.bridge();setRootAvailable(RootAccess.available());setRootMessage(rootAvailable?"Root 授权可用。需要在网页执行 Root 命令时，请勾选命令回传中的 Root 选项。":"尚未获得 Root 授权，请启用独立授权；若本机条件不可用，请查看检测结果。");output.setText("退出码："+r.exit+"\n标准输出：\n"+r.stdout+"\n错误输出：\n"+r.stderr+"\n"+r.error);readAdb();});},"root-probe").start();}
 private void startServer(){syncSession();if(server!=null||probing||endingAuthorization){Toast.makeText(this,"请先停止命令回传，或等待检测完成",0).show();return;}boolean allowRoot=rootToggle.isChecked();String host=ips.isEmpty()?"":ips.get(addresses.getSelectedItemPosition());if(!networks.isEmpty())getSharedPreferences("connection",0).edit().putString("consoleInterface",adbInterface()).apply();probing=true;startButton.setEnabled(false);probeButton.setEnabled(false);rootToggle.setAllowed(false);new Thread(()->{String failure="";try{if(allowRoot)RootAccess.check(this,false);ConsoleService.startSession(this,host,allowRoot);}catch(Exception e){failure=UserMessages.explain(e);}String error=failure;if(!dead)runOnUiThread(()->{probing=false;setRootAvailable(RootAccess.available());if(error.isEmpty())syncSession();else{sessionError.setText("启动失败："+error);sessionError.setVisibility(0);startButton.setEnabled(true);probeButton.setEnabled(true);}});},"start-console").start();}
 private void stopServer(){sessionError.setVisibility(8);ConsoleService.endSession();if(!ConsoleService.active(this))stopService(new Intent(this,ConsoleService.class));server=null;sessionUrl="";token="";sessionState.setText("回传已停止；旧连接码已作废");sessionHeading.state(false);setRootMessage(RootAccess.available()?"Root 授权可用，可勾选网页 Root 命令后重新启动回传。":"尚未获得有效 Root 授权，请重新授权。");addresses.setEnabled(true);rootToggle.setChecked(false);setRootAvailable(RootAccess.available());startButton.setEnabled(!probing);probeButton.setEnabled(!probing);}
 private void setStable(TextView view,String value){if(!view.getText().toString().equals(value))view.setText(value);}
 private void syncSession(){server=ConsoleService.server;if(sessionHeading!=null)sessionHeading.state(server!=null);if(server==null){addresses.setEnabled(true);startButton.setEnabled(!probing&&!endingAuthorization);probeButton.setEnabled(!probing&&!endingAuthorization);rootToggle.setAllowed(RootAccess.available()&&!probing&&!endingAuthorization);return;}sessionUrl=ConsoleService.url;token=ConsoleService.pin;bridgeMode=RootAccess.bridge();setStable(rootState,"状态："+(!RootAccess.available()?"尚未获得有效 Root 授权，请重新授权。":ConsoleService.root?"本次连接已允许 root 命令，切到后台仍保持回传。":"本次连接使用普通权限；停止后可选择网页 Root 命令。"));setStable(sessionState,"网址："+sessionUrl+"\n连接码："+token+"\n权限："+(ConsoleService.root?"普通 + root":"仅普通应用")+"\n后台保持连接，可切到其他应用");String warning=ConsoleService.error;if(!android.provider.Settings.canDrawOverlays(this))warning=(warning.isEmpty()?"":warning+"\n")+"悬浮窗未授权，服务仍在运行";sessionError.setVisibility(warning.isEmpty()?8:0);setStable(sessionError,warning);addresses.setEnabled(false);rootToggle.setChecked(ConsoleService.root);rootToggle.setAllowed(false);startButton.setEnabled(false);probeButton.setEnabled(false);}
 private final Runnable sessionTick=new Runnable(){public void run(){if(!dead){if(server!=null&&ConsoleService.server==null){server=null;sessionUrl="";token="";sessionState.setText("连接服务已停止，请重新启动");addresses.setEnabled(true);startButton.setEnabled(true);probeButton.setEnabled(!probing);}syncSession();refreshNetworkIfChanged();PhoneCompanion.refresh();if(phoneButton!=null)setStable(phoneButton,"手机助手 · "+PhoneCompanion.status());if(phoneRefresh!=null)phoneRefresh.run();AdbMaintenance.refresh(MainActivity.this);refreshRootIndicator();renderUpdate();if(remotePanel!=null)remotePanel.refresh();sessionHandler.postDelayed(this,1000);}}};
 private String adbHost(){if(ips.isEmpty())throw new IllegalArgumentException("请连接 Wi-Fi 并刷新地址");return AdbControl.ipv4(ips.get(addresses.getSelectedItemPosition()));}
 private CommandRunner controlRunner(){return RootAccess.runner(this);}
 private void updateIpState(){if(ipState==null)return;String draft=computerIp.getText().toString().trim();ipState.setTextColor(!draft.equals(appliedIp)?Design.YELLOW:Design.MUTED);ipState.setText(!draft.equals(appliedIp)?"待应用 · 当前生效："+(appliedIp.isEmpty()?"未设置":appliedIp):appliedIp.isEmpty()?"请填写电脑 IPv4 后确认":"当前生效："+appliedIp);}
 private void applyComputerIp(){if(adbBusy)return;final String pc,host,net,previous=appliedIp;try{pc=AdbControl.ipv4(computerIp.getText().toString().trim());host=networks.isEmpty()?"":adbHost();net=networks.isEmpty()?"":adbInterface();}catch(Exception e){ipState.setTextColor(Design.YELLOW);ipState.setText(e.getMessage());Toast.makeText(this,e.getMessage(),1).show();return;}NumberPad.dismiss();adbBusy=true;applyIp.setEnabled(false);wirelessToggle.setEnabled(false);wiredToggle.setEnabled(false);ipState.setTextColor(Design.MUTED);ipState.setText("正在应用…");new Thread(()->{CommandRunner runner=controlRunner();CommandRunner.Result r=null;String failure="";boolean enabled=false;try{synchronized(AdbControl.LOCK){CommandRunner.Result state=runner.execute(AdbControl.status(host,previous,net),true,5);if(state.exit!=0||state.timedOut||!state.error.isEmpty()||!state.stdout.contains("WIFI_ENABLED="))throw new IOException("无法读取 ADB 状态，请先完成 Root 提权");AdbStatus actual=new AdbStatus(state.stdout);if(actual.listen<0||actual.lan<0)throw new IOException("ADB 状态未知，请重新检测");enabled=actual.lan==1&&actual.listen==1;if(enabled){if(host.isEmpty())throw new IOException("暂无局域网地址，无法放行电脑 IP");r=runner.execute(AdbControl.wireless(true,host,pc,net),true,10);if(r.exit!=0||r.timedOut||!r.error.isEmpty())throw new IOException(r.stderr+" "+r.error);CommandRunner.Result verify=runner.execute(AdbControl.status(host,pc,net),true,5);if(verify.exit!=0||!verify.stdout.contains("WIRELESS=true")||!verify.stdout.contains("LISTEN=true"))throw new IOException("放行规则未通过检测，请重试");}getSharedPreferences("connection",0).edit().putString("computerIp",pc).putBoolean("adbManaged",enabled).putString("adbInterface",net).putString("adbNetwork",enabled?net+"|"+host+"|"+pc:"").commit();}}catch(Exception e){failure=UserMessages.explain(e);try{if(enabled&&!previous.isEmpty())runner.execute(AdbControl.wireless(true,host,previous,net),true,10);}catch(Exception ignored){}}finally{runner.close();}final String error=failure;final boolean active=enabled;if(!dead)runOnUiThread(()->{adbBusy=false;applyIp.setEnabled(true);if(error.isEmpty()){appliedIp=pc;updateIpState();Toast.makeText(this,active?"已应用，已允许此 IP 使用无线 ADB":"已保存，开启无线 ADB 后生效",1).show();if(active)startForegroundService(new Intent(this,ConsoleService.class));}else{ipState.setTextColor(Design.YELLOW);ipState.setText("应用失败："+error);Toast.makeText(this,"应用失败："+error,1).show();}readAdb();});},"apply-computer-ip").start();}
 private void adbNotice(String message){networkStatus.setTextColor(Design.YELLOW);setStable(networkStatus,message);networkStatus.setVisibility(message.isEmpty()?8:0);}
 private void setAdbChecks(AdbStatus state){
  wirelessEnabled=state.wirelessState()==1;syncingAdb=true;wirelessToggle.setChecked(wirelessEnabled);wiredToggle.setChecked(state.wired==1);
  wirelessToggle.setText(state.wirelessLabel());wirelessToggle.setTextColor(state.wirelessWarning()?Design.YELLOW:Design.TEXT);
  wiredToggle.setText(state.wired<0?"有线ADB - 状态未知":state.wired==1?"有线ADB - 已开启":"有线ADB - 已关闭");
  ((Design.AdbAction)wirelessToggle).state(state.wirelessState());((Design.AdbAction)wiredToggle).state(state.wired);syncingAdb=false;
  wirelessToggle.setEnabled(rootAvailable&&state.wirelessState()>=0);wiredToggle.setEnabled(rootAvailable&&state.wired>=0);
  String warning=networks.isEmpty()?"暂无局域网地址，内网穿透仍可使用":state.wirelessHint();
  if(wirelessEnabled&&!networks.isEmpty()&&!appliedIp.isEmpty()&&!networks.get(addresses.getSelectedItemPosition()).contains(appliedIp))warning="本次为跨网段IP · 请确认路由或 NAT 可达"+(warning.isEmpty()?"":"\n"+warning);
  adbNotice(warning);
 }
 private void unknownAdb(String label){wirelessToggle.setText("无线ADB - "+label);wirelessToggle.setTextColor("检测中".equals(label)?Design.MUTED:Design.YELLOW);wiredToggle.setText("有线ADB - "+label);((Design.AdbAction)wirelessToggle).state(-1);((Design.AdbAction)wiredToggle).state(-1);adbNotice("检测中".equals(label)?"":"无法确认 ADB 状态，请检查 Root 授权并重新检测");}

 private void readAdb(){if(adbBusy)return;String command;try{command=networks.isEmpty()?AdbControl.status("","",""):AdbControl.status(adbHost(),appliedIp,adbInterface());}catch(Exception e){unknownAdb("状态未知");output.setText(e.getMessage());return;}adbBusy=true;applyIp.setEnabled(false);wirelessToggle.setEnabled(false);wiredToggle.setEnabled(false);unknownAdb("检测中");new Thread(()->{CommandRunner runner=controlRunner();CommandRunner.Result r;synchronized(AdbControl.LOCK){r=runner.execute(command,true,5);}runner.close();if(!dead)runOnUiThread(()->{adbBusy=false;applyIp.setEnabled(true);if(r.exit==0&&!r.timedOut&&r.error.isEmpty()&&r.stdout.contains("WIRED=")){setAdbChecks(new AdbStatus(r.stdout));output.setText("已读取车机实际设置。\n"+wirelessToggle.getText()+"\n"+wiredToggle.getText()+"\n已允许表示放行规则生效，电脑连接需另行验证。");}else{wirelessToggle.setEnabled(false);wiredToggle.setEnabled(false);unknownAdb("状态未知");output.setText("读取失败，请先完成 Root 提权：\n"+r.stderr+"\n"+r.error);}});},"adb-state").start();}
 private void changeAdb(boolean wireless,boolean on){
  if(adbBusy)return;
  syncingAdb=true;(wireless?wirelessToggle:wiredToggle).setChecked(!on);syncingAdb=false;
  final String command,host,net,peer=appliedIp;
  try{host=networks.isEmpty()?"":adbHost();net=networks.isEmpty()?"":adbInterface();if(wireless&&on&&host.isEmpty())throw new IllegalArgumentException("请连接 Wi-Fi 或开启车机热点，再开启无线 ADB");command=wireless?(on?AdbControl.wireless(true,host,peer,net):AdbControl.wireless(false,"","","")):AdbControl.wired(on);}
  catch(Exception e){adbNotice(e.getMessage());output.setText(e.getMessage());Toast.makeText(this,e.getMessage(),1).show();return;}
  adbBusy=true;applyIp.setEnabled(false);wirelessToggle.setEnabled(false);wiredToggle.setEnabled(false);output.setText("正在更新 ADB 设置…");
  new Thread(()->{
   CommandRunner runner=controlRunner();AdbStatus verified=null;String failure="";
   try{verified=AdbChange.apply(runner,command,host.isEmpty()?AdbControl.status("","",""):AdbControl.status(host,peer,net),wireless,on,()->{
    if(wireless&&!getSharedPreferences("connection",0).edit().putBoolean("adbManaged",on).putString("adbInterface",on?net:getSharedPreferences("connection",0).getString("adbInterface","")).putString("adbNetwork",on?net+"|"+host+"|"+peer:"").commit())throw new IOException("设置保存失败，请重试");
   });}catch(Exception e){failure=UserMessages.explain(e);}finally{runner.close();}
   final AdbStatus actual=verified;final String error=failure;
   if(!dead)runOnUiThread(()->{
    adbBusy=false;applyIp.setEnabled(true);
    if(!error.isEmpty()){adbNotice("修改失败："+error);output.setText("修改失败："+error);Toast.makeText(this,"修改失败："+error,1).show();readAdb();return;}
    setAdbChecks(actual);String result=(wireless?"无线ADB":"有线ADB")+(on?"已开启":"已关闭");output.setText(result+(wireless&&!on?"；内网穿透的本机通道不受影响":""));Toast.makeText(this,result,0).show();
    if(wireless){if(on)startForegroundService(new Intent(this,ConsoleService.class));else if(!ConsoleService.active(this))stopService(new Intent(this,ConsoleService.class));}
   });
  },"adb-change").start();
 }

