 private class RootOption extends CheckBox {
  private boolean allowed;
  RootOption(){super(MainActivity.this);}
  void setAllowed(boolean value){allowed=value;setTextColor(value?Design.TEXT:Design.MUTED);}
  @Override public boolean performClick(){
   String reason="";
   if(ConsoleService.server!=null)reason=ConsoleService.root?"当前回传已允许 Root 命令。若需修改，请先点击【停止回传】。":"请先点击【停止回传】，勾选此项后再启动命令回传。";
   else if(probing)reason="正在检测 Root，请等待检测结束后再勾选。";
   else if(!rootAvailable)reason="请先点击【启用独立授权】并确认。检测到 Root 授权可用后，即可勾选。";
   else if(!allowed)reason="正在更新授权状态，请稍后再勾选。";
   if(!reason.isEmpty()){Design.show(new android.app.AlertDialog.Builder(MainActivity.this).setTitle("如何启用网页 Root 命令").setMessage(reason).setPositiveButton("明白",null));return true;}
   return super.performClick();
  }
 }
