 private void enableIndependentRoot(){if(probing||endingAuthorization||RootAccess.busy()){Toast.makeText(this,"正在处理授权，请稍后重试",0).show();return;}probing=true;independentRootButton.setEnabled(false);probeButton.setEnabled(false);startButton.setEnabled(false);setRootAvailable(false);setRootMessage("正在建立星匣独立授权…");new Thread(()->{CommandRunner.Result result=RootAccess.enableIndependent(this);if(!dead)runOnUiThread(()->{probing=false;independentRootButton.setEnabled(true);probeButton.setEnabled(true);setRootAvailable(RootAccess.available());syncSession();setRootMessage(result.error.isEmpty()?RootAccess.message():result.error);output.setText(result.stdout+"\n"+result.error);if(rootAvailable)readAdb();});},"starbox-own-root").start();}
