 private void endAuthorizationNow(){if(UpdateService.state().phase==UpdateService.Phase.INSTALLING){Toast.makeText(this,"正在安装，请等待完成后再结束提权",1).show();return;}UpdateService.stopForRevocation();if(endingAuthorization)return;rootConsentShown=true;endingAuthorization=true;RuntimeRecovery.cancel();RootAccess.beginRevoke();setRootAvailable(false);rootToggle.setChecked(false);new Thread(()->{CommandRunner.Result stopped=RootAccess.stop(this,true);RootAccess.finishRevoke();if(!dead)runOnUiThread(()->{endingAuthorization=false;probing=false;setRootAvailable(false);syncSession();setRootMessage(stopped.error.isEmpty()?"提权已结束，需要使用时请再次启用独立授权。":stopped.error);if(!stopped.error.isEmpty())Toast.makeText(this,stopped.error,1).show();wirelessToggle.setEnabled(false);wiredToggle.setEnabled(false);startButton.setEnabled(server==null);probeButton.setEnabled(true);});},"end-root").start();}
 private void requestOverlayPermission(){
  if(android.provider.Settings.canDrawOverlays(this)){Toast.makeText(this,"已具有悬浮窗权限，无需再次授权",1).show();return;}
  Intent[] routes={new Intent(android.provider.Settings.ACTION_MANAGE_OVERLAY_PERMISSION,android.net.Uri.parse("package:"+getPackageName())),new Intent(android.provider.Settings.ACTION_MANAGE_OVERLAY_PERMISSION),new Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS,android.net.Uri.parse("package:"+getPackageName()))};
  for(Intent route:routes){try{if(route.resolveActivity(getPackageManager())!=null){startActivity(route);return;}}catch(android.content.ActivityNotFoundException|SecurityException unavailable){/* Some car firmware removes or restricts Android settings activities. */}}
  Design.show(new android.app.AlertDialog.Builder(this).setTitle("车机未提供悬浮窗授权入口").setMessage("请在车机的应用管理或权限管理中，为E02星匣开启悬浮窗权限，再返回本程序。若系统没有此选项，可使用你已有的权限管理工具。\n\n未授权时，手机助手等服务仍可使用，保活悬浮窗暂不显示。").setPositiveButton("明白",null));
 }
 private void startMirrorTest(){if(UpdateService.busy){Toast.makeText(this,"请等待当前任务完成",0).show();return;}UpdateService.testMirrors(this);renderUpdate();}
 private void renderUpdate(){UpdateService.State state=UpdateService.state();if(updateStatus!=null)setStable(updateStatus,state.message);if(mirrorHint!=null)mirrorHint.setVisibility(state.phase==UpdateService.Phase.CHECK_FAILED?0:8);if(mirrorTestButton!=null){mirrorTestButton.setEnabled(!UpdateService.busy);setStable(mirrorTestButton,state.phase==UpdateService.Phase.TESTING?"正在测试镜像站…":"自动测试镜像站");}if(updateNotice!=null){String notice=state.notice();updateNotice.setVisibility(notice.isEmpty()?8:0);setStable(updateNotice,notice);}String mirror=UpdateService.takeMirror();if(!mirror.isEmpty())Design.show(new android.app.AlertDialog.Builder(this).setTitle("找到可用镜像站").setMessage(mirror.replace("https://","")+" 已通过更新清单和安装包入口测试。\n\n是否将此镜像站用于今后的更新检查和下载？").setPositiveButton("使用",(d,w)->{getSharedPreferences("updates",0).edit().putString("proxy",mirror).apply();syncUpdateRoute();UpdateService.check(this,true);}).setNegativeButton("取消",null));
  if(state.phase==UpdateService.Phase.READY&&state.release!=null){String id=state.release.sha;if(!id.equals(installPromptId)){installPromptId=id;askInstall();}}}
 private void showUpdateDetails(){UpdateService.State state=UpdateService.state();if(state.phase==UpdateService.Phase.CHECK_FAILED){selectPage(3);if(updateCard!=null)updateCard.post(()->updateCard.requestRectangleOnScreen(new android.graphics.Rect(0,0,updateCard.getWidth(),dp(310)),false));return;}if(state.ready()){askInstall();return;}if(state.release==null)return;
  if(updateDialog!=null&&updateDialog.isShowing())return;android.app.AlertDialog.Builder builder=new android.app.AlertDialog.Builder(this).setTitle("新版本 "+state.release.version).setMessage(state.release.notes+(state.message.isEmpty()?"":"\n\n"+state.message));
  if(state.phase==UpdateService.Phase.DOWNLOADING)builder.setPositiveButton("取消下载",(d,w)->UpdateService.cancel()).setNegativeButton("关闭",null);else if(state.phase==UpdateService.Phase.INSTALLING)builder.setPositiveButton("明白",null);else builder.setPositiveButton("下载",(d,w)->UpdateService.download(this)).setNegativeButton("取消",null);updateDialog=Design.show(builder);updateDialog.setOnDismissListener(d->updateDialog=null);}
 private void askInstall(){UpdateService.State state=UpdateService.state();if(!state.ready()||state.release==null)return;if(updateDialog!=null&&updateDialog.isShowing())updateDialog.dismiss();updateDialog=Design.show(new android.app.AlertDialog.Builder(this).setTitle("安装新版本 "+state.release.version+"？").setMessage("安装包已保存在下载文件夹，并通过完整性、版本、包名和原签名校验。\n\n确认后使用当前 Root 授权覆盖安装，保留现有配置。程序可能会关闭，安装成功后自动删除安装包。\n\n"+state.release.notes).setPositiveButton("安装",(d,w)->UpdateService.install(this)).setNegativeButton("取消",null));updateDialog.setOnDismissListener(d->updateDialog=null);}
 private void confirmInitialization(){
  android.app.AlertDialog d=new android.app.AlertDialog.Builder(this).setTitle("初始化 E02星匣？").setMessage("将清除星匣的所有配置、设置、连接凭证和首次使用确认记录，并停止手机助手、命令回传、内网穿透和本次 Root 提权。此操作无法撤销。\n\n初始化后程序会关闭。请重新打开 E02星匣，查看首次启动的免责声明与风险告知，并重新配置所需功能。\n\n不会恢复车机出厂设置，也不会修改当前系统 ADB 设置；下载文件夹里的截图会保留。").setNegativeButton("取消",null).setPositiveButton("确认初始化",(dialog,which)->initializeApplication()).create();
  d.setOnShowListener(v->{Design.dialog(d);Design.actionColor(d.getButton(android.app.AlertDialog.BUTTON_POSITIVE),false);});d.show();
 }
 private void initializeApplication(){
  if(UpdateService.state().phase==UpdateService.Phase.INSTALLING){Toast.makeText(this,"正在安装，请等待完成后再初始化",1).show();return;}if(dead)return;RuntimeRecovery.cancel();RootAccess.beginRevoke();dead=true;sessionHandler.removeCallbacksAndMessages(null);NumberPad.dismiss();PhoneCompanion.stop();UpdateService.cancel();RemoteService.stop(this);stopService(new Intent(this,UpdateService.class));
  new Thread(()->{try{
   ConsoleService.endSession();String secret=exitBridgeToken();CommandRunner.Result stopped=RootAccess.stop(this,true);if(!stopped.error.isEmpty())throw new IOException(stopped.error);if(!StatusBarEntry.disableForExit(this))throw new IOException(StatusBarEntry.error);
   if(!secret.isEmpty()){CommandRunner.Result check=new BridgeRunner(secret,false).execute("id",true,2);if(check.exit==0&&!check.timedOut&&check.stdout.matches("(?s).*\\buid=0\\(root\\).*"))throw new IOException("Root 提权尚未停止，请稍后重试");}
   stopService(new Intent(this,ConsoleService.class));
   android.app.ActivityManager manager=(android.app.ActivityManager)getSystemService(ACTIVITY_SERVICE);
   if(manager==null||!manager.clearApplicationUserData())throw new IOException("系统未允许初始化，请在车机应用管理中清除星匣的数据");
  }catch(Exception e){runOnUiThread(()->{RootAccess.finishRevoke();dead=false;Toast.makeText(this,"初始化未完成："+UserMessages.explain(e),Toast.LENGTH_LONG).show();recreate();});}},"starbox-initialize").start();
 }
 private String exitBridgeToken(){if(!bridgeSecret.isEmpty())return bridgeSecret;try{byte[] bytes=new byte[32];try(DataInputStream in=new DataInputStream(new FileInputStream(new File(getFilesDir(),"bridge-token")))){in.readFully(bytes);if(in.read()!=-1)return "";}String secret=new String(bytes,"US-ASCII");return secret.matches("[0-9a-f]{32}")?secret:"";}catch(IOException ignored){return "";}}
 private CheckBox runtimeToggle(LinearLayout row,String name){CheckBox option=new CheckBox(this);option.setText(name);styleToggle(option);option.setTextSize(18);row.addView(option,new LinearLayout.LayoutParams(0,dp(54),1));option.setOnCheckedChangeListener((view,on)->saveRuntimeOptions());return option;}
 private void syncRuntimeOptions(){RuntimePolicy.Snapshot state=RuntimeSettings.snapshot(this);boolean healthy=RuntimeSettings.healthy(this);syncingRuntime=true;for(CheckBox option:new CheckBox[]{keepAliveToggle,autoStartToggle})if(option!=null)option.setEnabled(healthy);if(keepAliveToggle!=null)keepAliveToggle.setChecked(state.keepAlive);if(autoStartToggle!=null)autoStartToggle.setChecked(state.autoStart);syncingRuntime=false;if(quitButton!=null)ExitConfirm.style(quitButton,!healthy||ExitPolicy.blocked(state.keepAlive,state.autoStart,state.parkedRemote,RuntimeSettings.wakeRecovery(this)));syncKeepAliveChildren();}
 private void saveRuntimeOptions(){if(syncingRuntime||keepAliveToggle==null||autoStartToggle==null)return;boolean saved=RuntimeSettings.configure(this,keepAliveToggle.isChecked(),autoStartToggle.isChecked(),RuntimeSettings.snapshot(this).parkedRemote);syncRuntimeOptions();if(!saved)Toast.makeText(this,"设置未保存，请检查星匣的存储空间后重试",1).show();else{StatusBarEntry.sync(this);syncKeepAliveChildren();RuntimeRecovery.cancel();startForegroundService(new Intent(this,ConsoleService.class).setAction("options"));}}
 private void syncKeepAliveChildren(){
  if(statusBarToggle==null||overlayToggle==null)return;syncingChildren=true;boolean enabled=RuntimeSettings.healthy(this)&&RuntimeSettings.snapshot(this).keepAlive;
  statusBarToggle.setChecked(StatusBarEntry.selected(this));overlayToggle.setChecked(getSharedPreferences("connection",0).getBoolean("overlay",true));statusBarToggle.setEnabled(enabled);overlayToggle.setEnabled(enabled);overlayPermissionButton.setEnabled(enabled&&overlayToggle.isChecked());overlayCenterButton.setEnabled(enabled&&overlayToggle.isChecked());
  keepAliveChildHint.setText(!enabled?"开启星匣后台保活后可使用这两个子项目，原有选择会保留。":!StatusBarEntry.error.isEmpty()?StatusBarEntry.error:"悬浮窗贴近边缘、拖不动时，可恢复到屏幕中央。状态栏入口由系统加载，不阻止车机休眠。");syncingChildren=false;
 }
 private void saveKeepAliveChild(boolean statusBar,boolean on){
  if(syncingChildren)return;boolean saved;if(statusBar)saved=StatusBarEntry.select(this,on);else{SharedPreferences prefs=getSharedPreferences("connection",0);boolean before=prefs.getBoolean("overlay",true);saved=prefs.edit().putBoolean("overlay",on).commit();if(!saved)prefs.edit().putBoolean("overlay",before).commit();}syncKeepAliveChildren();
  if(!saved){Toast.makeText(this,statusBar?StatusBarEntry.error:"悬浮窗设置未保存，请重试",1).show();return;}
  startForegroundService(new Intent(this,ConsoleService.class).setAction("options"));if(!statusBar&&on&&!android.provider.Settings.canDrawOverlays(this))requestOverlayPermission();
 }
 private void showExitRestriction(){RuntimePolicy.Snapshot state=RuntimeSettings.snapshot(this);if(exitDialog!=null&&exitDialog.isShowing())return;exitDialog=ExitConfirm.show(this,state.keepAlive,state.autoStart,state.parkedRemote,RuntimeSettings.wakeRecovery(this),()->selectPage(2));exitDialog.setOnDismissListener(dialog->exitDialog=null);}
 private void requestExit(){if(dead)return;syncRuntimeOptions();if(!RuntimeSettings.healthy(this)){Design.show(new android.app.AlertDialog.Builder(this).setTitle("暂时无法退出").setMessage("无法读取保活设置，请重新打开星匣后重试。").setPositiveButton("明白",null));return;}RuntimePolicy.Snapshot state=RuntimeSettings.snapshot(this);if(ExitPolicy.blocked(state.keepAlive,state.autoStart,state.parkedRemote,RuntimeSettings.wakeRecovery(this))){showExitRestriction();return;}if(UpdateService.state().phase==UpdateService.Phase.INSTALLING){Toast.makeText(this,"正在安装，请等待完成后再退出",1).show();return;}RuntimePolicy.Decision decision=RuntimeSettings.requestExit(this);if(decision.has(RuntimePolicy.Effect.EXIT_BLOCKED)){syncRuntimeOptions();showExitRestriction();return;}if(decision.has(RuntimePolicy.Effect.SAVE_ERROR))Toast.makeText(this,"运行设置保存失败，程序将关闭；下次打开后请检查设置",1).show();exitApplication();}
 private void exitAfterDecliningRisk(){if(RiskNotice.accepted(this))return;exitApplication();}
 private void exitApplication(){if(dead)return;if(RiskNotice.accepted(this)){RuntimePolicy.Snapshot state=RuntimeSettings.snapshot(this);if(ExitPolicy.blocked(state.keepAlive,state.autoStart,state.parkedRemote,RuntimeSettings.wakeRecovery(this))){syncRuntimeOptions();showExitRestriction();return;}}if(UpdateService.state().phase==UpdateService.Phase.INSTALLING){Toast.makeText(this,"正在安装，请等待完成后再退出",1).show();return;}RuntimeRecovery.cancel();RootAccess.beginRevoke();dead=true;sessionHandler.removeCallbacksAndMessages(null);PhoneCompanion.stop();getSharedPreferences("connection",0).edit().putBoolean("appActive",false).putBoolean("adbManaged",false).apply();UpdateService.cancel();RemoteService.stop(this);stopService(new Intent(this,UpdateService.class));new Thread(()->{ConsoleService.endSession();CommandRunner.Result stopped=RootAccess.stop(this,false);if(!StatusBarEntry.disableForExit(this)&&stopped.error.isEmpty())stopped.error=StatusBarEntry.error;stopService(new Intent(this,ConsoleService.class));if(!stopped.error.isEmpty()){RootAccess.finishRevoke();runOnUiThread(()->{dead=false;setRootAvailable(false);setRootMessage(stopped.error);Toast.makeText(this,"退出未完成："+stopped.error,1).show();});return;}runOnUiThread(()->{finishAndRemoveTask();new android.os.Handler(android.os.Looper.getMainLooper()).postDelayed(()->android.os.Process.killProcess(android.os.Process.myPid()),400);});},"starbox-exit").start();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==RemotePanel.IMPORT&&result==RESULT_OK&&data!=null&&data.getData()!=null)remotePanel.importUri(data.getData());}
 @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);if(!RiskNotice.accepted(this)||dead)return;if(getSharedPreferences("updates",0).getBoolean("auto",true))UpdateService.check(this,false);}
 @Override protected void onResume(){super.onResume();visible=true;syncRuntimeOptions();if(!RiskNotice.accepted(this)||dead)return;PhoneCompanion.attach(this);refreshNetworkIfChanged();syncSession();checkBridgeOnResume();if(server!=null)readAdb();sessionHandler.removeCallbacks(sessionTick);sessionHandler.post(sessionTick);}
 @Override public void onBackPressed(){if(!NumberPad.dismiss())super.onBackPressed();}
 @Override protected void onStop(){NumberPad.dismiss();PhoneCompanion.detach(this);sessionHandler.removeCallbacks(sessionTick);super.onStop();}
 @Override protected void onPause(){visible=false;super.onPause();}
 @Override protected void onDestroy(){if(rootConsentDialog!=null){rootConsentDialog.dismiss();rootConsentDialog=null;}if(exitDialog!=null){exitDialog.dismiss();exitDialog=null;}if(updateDialog!=null){updateDialog.dismiss();updateDialog=null;}if(riskDialog!=null){riskDialog.dismiss();riskDialog=null;}PhoneCompanion.detach(this);dead=true;sessionHandler.removeCallbacks(sessionTick);if(probeRunner!=null)probeRunner.close();super.onDestroy();}
